{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/topic-chips.json
    A centered row of topic pills (static links). tone inverse: on a dark band with an icon per topic; default: outlined.
    Props (p): topics, tone. *}
{var $v_topics = ($p['topics'] ?? null)}
{var $v_tone = ($p['tone'] ?? 'default')}
{capture $c_3}
  {foreach ui_l($v_topics) as $v_topic}
    {if ui_t(ui_eq($v_tone, 'inverse'))}
      {capture $c_1}
        {if ui_t(ui_get($v_topic, ['icon']))}
          {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => ui_s(ui_get($v_topic, ['icon'])), 'Size' => 16]])|noescape}
        {/if}
        {=ui_text(ui_get($v_topic, ['name']))}
      {/capture}
      {=ui_include('ui/button/button.latte', ['p' => ['Href' => '#/', 'Variant' => 'ghost', 'Size' => 'sm', 'Class' => 'gap-2 text-background inset-ring-background/30 hover:bg-background/10', 'Attrs' => ui_attrs(['data-testid', 'hero-topic'])], 'children' => $c_1])|noescape}
    {else}
      {capture $c_2}
        {=ui_text(ui_get($v_topic, ['name']))}
      {/capture}
      {=ui_include('ui/button/button.latte', ['p' => ['Href' => '#/', 'Variant' => 'outline', 'Size' => 'sm', 'Attrs' => ui_attrs(['data-testid', 'hero-topic'])], 'children' => $c_2])|noescape}
    {/if}
  {/foreach}
{/capture}
{=ui_include('ui/group/group.latte', ['p' => ['Gap' => '2', 'Align' => 'center', 'Justify' => 'center', 'Class' => 'flex-wrap', 'Attrs' => ui_attrs(['data-testid', 'hero-topics'])], 'children' => $c_3])|noescape}
